function s(t,u){if(u<1)return{gratuityAmount:0,basicSalary:t,yearsOfService:u};const o=t/30;let n=0;u<=5?n=o*21*u:n=o*21*5+o*30*(u-5);const A=t*24;return n=Math.min(n,A),{gratuityAmount:n,basicSalary:t,yearsOfService:u}}function m(t,u,o=!1){if(o){const A=t/(1+u/100),g=t-A;return{netAmount:A,vatAmount:g,totalAmount:t}}const n=t*(u/100);return{netAmount:t,vatAmount:n,totalAmount:t+n}}function a(t,u,o,n){const{netAmount:A,vatAmount:g,totalAmount:c}=m(t,u,o);return{netAmount:A,cgst:n?0:g/2,sgst:n?0:g/2,igst:n?g:0,totalAmount:c}}export{m as c,a as g,s as u};
